using System;
using Scheduling;
// H1 [happy_path]: Expands weekdays selects next occurrence and round trips CET
{
    var engine = new RecurrenceEngine();
    var job = new Job
    {
        Id = "job-1",
        Duration = TimeSpan.FromHours(1),
        Priority = 3,
        RequiredSkill = "dispatch"
    };
    var slot = new Slot
    {
        Start = new DateTime(2024, 1, 8, 9, 0, 0),
        End = new DateTime(2024, 1, 8, 10, 0, 0)
    };
    
    var expanded = engine.Expand(job, slot, 3);
    
    Check.SequenceEqual(new[]
    {
        new DateTime(2024, 1, 8, 9, 0, 0),
        new DateTime(2024, 1, 9, 9, 0, 0),
        new DateTime(2024, 1, 10, 9, 0, 0)
    }, expanded);
    
    var next = engine.NextOccurrence(job, new DateTime(2024, 1, 8, 9, 0, 0));
    Check.NotNull(next);
    Check.Equal(new DateTime(2024, 1, 9, 9, 0, 0), next.Value);
    
    var utc = engine.ToUtc(next.Value, "CET");
    Check.Equal(new DateTime(2024, 1, 9, 8, 0, 0), utc);
    Check.Equal(new DateTime(2024, 1, 9, 9, 0, 0), engine.ToLocal(utc, "CET"));
}

// E1 [empty_or_invalid]: Empty job identifier returns no occurrences
{
    var engine = new RecurrenceEngine();
    var job = new Job
    {
        Id = "",
        Duration = TimeSpan.FromHours(1),
        Priority = 1,
        RequiredSkill = "dispatch"
    };
    var slot = new Slot
    {
        Start = new DateTime(2024, 1, 8, 9, 0, 0),
        End = new DateTime(2024, 1, 8, 10, 0, 0)
    };
    
    var expanded = engine.Expand(job, slot, 1);
    
    Check.Equal(0, expanded.Count);
}

