    };
    var secondSlot = new Slot
    {
        Start = new DateTime(2024, 3, 4, 9, 0, 0),
        End = new DateTime(2024, 3, 4, 10, 0, 0)
    };
    
    var retainedFirstView = engine.Expand(job, firstSlot, 2);
    Check.SequenceEqual(new[]
    {
        new DateTime(2024, 2, 5, 9, 0, 0),
        new DateTime(2024, 2, 6, 9, 0, 0)
